    counts = {}
    left = 0
    best = 0
    for right in range(len(s)):
        counts[s[left]] = counts.get(s[left], 0) + 1
        while len(counts) > k:
            counts[s[left]] -= 1
            if counts[s[left]] == 0:
                del counts[s[left]]
            left += 1
        best = max(best, right - left + 1)
    return best

